package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.notification.*;
import cn.mop.domain.notification.OwnNotificationPreferenceRepository.*;
import cn.mop.domain.notification.OwnNotificationPreferenceDraft.LevelPreference;
import cn.mop.domain.notification.DeliveryReceiptState.Channel;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Isolated HTTP boundary checks; real OIDC/PG/CSRF validation is recorded separately. */
class OwnNotificationPreferenceControllerTest {
    static final String ACTOR="77000000-0000-4000-8000-000000000001",TENANT="77000000-0000-4000-8000-000000000002",ID="77000000-0000-4000-8000-000000000003",OTHER="77000000-0000-4000-8000-000000000004";
    static final Instant TIME=Instant.parse("2026-10-04T23:00:00.123Z");
    PlatformRepository platform;OwnNotificationPreferenceRepository repo;OwnNotificationPreferenceController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);repo=mock(OwnNotificationPreferenceRepository.class);controller=new OwnNotificationPreferenceController(platform,repo);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"viewer",7,true)));when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(repo.current(any())).thenReturn(Optional.of(row(1,draft())));when(repo.get(any(),any())).thenReturn(row(1,draft()));when(repo.create(any(),any())).thenAnswer(c->row(1,c.getArgument(1)));when(repo.update(any(),any(),anyLong(),any())).thenAnswer(c->row((long)c.getArgument(2)+1,c.getArgument(3)));}
    Access access(){return new Access(ACTOR,TENANT,7,"trace-preference");}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/my/notification-preferences"+(method.equals("PATCH")?"/"+ID:""));r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","trace-preference");r.addHeader("Idempotency-Key","test-preference-key");return r;}
    OwnNotificationPreferenceDraft draft(){return new OwnNotificationPreferenceDraft(UUID.fromString(TENANT),UUID.fromString(ACTOR),null,null,null);}
    Snapshot row(long v,OwnNotificationPreferenceDraft d){return new Snapshot(ID,TENANT,v,d,ACTOR,7,TIME,TIME);}
    ObjectNode input(){return mapper.createObjectNode().put("expected_version",0).put("intent",OwnNotificationPreferenceController.INTENT).putNull("requested_level").putNull("requested_channels").putNull("requested_quiet_window");}
    static Map<?,?> data(Object out){return (Map<?,?>)((Map<?,?>)out).get("data");}
    static void status(int expected,org.junit.jupiter.api.function.Executable work){assertEquals(expected,assertThrows(DomainException.class,work).status);}
    @Test void creationUsesCurrentScopeAndNeverActivatesOrBindsReceiver(){var out=data(controller.write(null,input(),request("POST")));assertEquals(ACTOR,out.get("owner_id"));assertEquals(TENANT,out.get("tenant_id"));assertEquals(1L,out.get("version"));assertEquals(false,out.get("effective"));assertNull(out.get("delivery_decision"));assertNull(out.get("verified_receiver_id"));assertEquals(false,out.get("notification_dispatched"));assertEquals("CONFIG_PENDING",out.get("configuration_status"));assertEquals("Asia/Shanghai",out.get("timezone"));verify(repo).create(access(),draft());verify(repo).authorizeCurrentAccess(access(),null);}
    @Test void missingFieldsAndExtraIdentityOrSecretFieldsNeverWrite(){var initial=input();for(String f:List.of("expected_version","intent","requested_level","requested_channels","requested_quiet_window")){var n=initial.deepCopy();n.remove(f);status(400,()->controller.write(null,n,request("POST")));}for(String f:List.of("owner_id","tenant_id","verified_receiver_id","access_key","effective","delivery_decision","notification_dispatched","timezone")){var n=initial.deepCopy().put(f,"SYNTHETIC");status(400,()->controller.write(null,n,request("POST")));}verify(repo,never()).create(any(),any());}
    @Test void invalidIntentAndNonIntegralVersionsAreRejected(){for(var n:List.of(input().put("intent","ENABLE"),input().put("expected_version",0.0),input().put("expected_version",1),input().put("expected_version","0")))status(400,()->controller.write(null,n,request("POST")));for(long v:new long[]{-1,0,9007199254740990L})status(400,()->controller.write(ID,input().put("expected_version",v),request("PATCH")));}
    @Test void channelNullEmptyAndCanonicalSetRemainDifferent(){assertNull(data(controller.write(null,input(),request("POST"))).get("requested_channels"));var empty=input();empty.putArray("requested_channels");assertEquals(List.of(),data(controller.write(null,empty,request("POST"))).get("requested_channels"));var values=input();values.putArray("requested_channels").add("SMS").add("EMAIL");assertEquals(List.of("EMAIL","SMS"),data(controller.write(null,values,request("POST"))).get("requested_channels"));}
    @Test void duplicateUnknownNullAndOversizedChannelsFailBeforeWrite(){for(String s:List.of("[\"SMS\",\"SMS\"]","[null]","[\"unknown\"]","[1]","[]")){if(s.equals("[]"))continue;var n=input();try{n.set("requested_channels",mapper.readTree(s));}catch(Exception e){throw new AssertionError(e);}status(400,()->controller.write(null,n,request("POST")));}var over=input();var list=over.putArray("requested_channels");for(int i=0;i<7;i++)list.add("EMAIL");status(400,()->controller.write(null,over,request("POST")));status(400,()->controller.write(null,input().put("requested_channels","EMAIL"),request("POST")));}
    @Test void levelOnlyAcceptsExplicitKnownEnumOrNull(){for(String s:List.of("P1_ONLY","P1_P2","ALL"))assertEquals(s,data(controller.write(null,input().put("requested_level",s),request("POST"))).get("requested_level"));for(var n:List.of(input().put("requested_level","P1"),input().put("requested_level",false),input().put("requested_level","all")))status(400,()->controller.write(null,n,request("POST")));}
    @Test void explicitQuietUnknownFalseAndCrossMidnightRoundTrip(){for(Boolean enabled:Arrays.asList(null,false)){var n=input();var q=n.putObject("requested_quiet_window");if(enabled==null)q.putNull("enabled");else q.put("enabled",enabled);q.putNull("start").putNull("end");var actual=(Map<?,?>)data(controller.write(null,n,request("POST"))).get("requested_quiet_window");assertEquals(enabled,actual.get("enabled"));assertNull(actual.get("start"));}var n=input();n.putObject("requested_quiet_window").put("enabled",true).put("start","22:30").put("end","07:00");var actual=(Map<?,?>)data(controller.write(null,n,request("POST"))).get("requested_quiet_window");assertEquals("22:30",actual.get("start"));assertEquals("07:00",actual.get("end"));}
    @Test void quietWindowRejectsHiddenTimesSecondsDuplicatesAndTimezoneOverride(){for(String time:List.of("22:00:00","22:00\n","24:00","22:00.001","2:00")){var n=input();n.putObject("requested_quiet_window").put("enabled",true).put("start",time).put("end","07:00");status(400,()->controller.write(null,n,request("POST")));}for(var q:List.of(mapper.createObjectNode().put("enabled",false).put("start","22:00").put("end","07:00"),mapper.createObjectNode().put("enabled",true).put("start","07:00").put("end","07:00"),mapper.createObjectNode().put("enabled","true").putNull("start").putNull("end"),mapper.createObjectNode().put("enabled",false).putNull("start").putNull("end").put("timezone","UTC"))){var n=input();n.set("requested_quiet_window",q);status(400,()->controller.write(null,n,request("POST")));}}
    @Test void currentAbsenceIsExplicitAndDoesNotCreateADefault(){when(repo.current(access())).thenReturn(Optional.empty());var out=data(controller.current(request("GET")));assertEquals(false,out.get("exists"));assertNull(out.get("current"));assertEquals(ACTOR,out.get("owner_id"));verify(repo,never()).create(any(),any());verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void currentAndDetailReturnOwnerDraftOnly(){var out=data(controller.current(request("GET")));assertEquals(true,out.get("exists"));assertEquals(ID,((Map<?,?>)out.get("current")).get("id"));assertEquals(ID,data(controller.get(ID,request("GET"))).get("id"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void updateUsesExpectedVersionAndOriginalReceiptAuthorization(){assertEquals(2L,data(controller.write(ID,input().put("expected_version",1),request("PATCH"))).get("version"));verify(repo).update(access(),ID,1,draft());verify(repo).authorizeCurrentAccess(access(),ID);}
    @Test void cachedOriginalReceiptDoesNotExecuteMutationAgain(){doAnswer(c->{((Runnable)c.getArgument(6)).run();return Map.of("original",true);}).when(platform).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());assertEquals(true,data(controller.write(ID,input().put("expected_version",1),request("PATCH"))).get("original"));verify(repo).authorizeCurrentAccess(access(),ID);verify(repo,never()).update(any(),any(),anyLong(),any());}
    @Test void hashCanonicalizesObjectKeysButBindsChannelOrderNullAndVersion(){var a=input();a.putArray("requested_channels").add("SMS").add("EMAIL");var b=mapper.createObjectNode();var keys=new ArrayList<String>();a.fieldNames().forEachRemaining(keys::add);Collections.reverse(keys);for(String k:keys)b.set(k,a.get(k));var c=a.deepCopy();c.withArray("requested_channels").removeAll().add("EMAIL").add("SMS");controller.write(null,a,request("POST"));controller.write(null,b,request("POST"));controller.write(null,c,request("POST"));controller.write(null,input(),request("POST"));controller.write(ID,a.deepCopy().put("expected_version",1),request("PATCH"));var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(5)).idempotentAuthorized(any(),any(),any(),any(),hashes.capture(),anyLong(),any(),any());var h=hashes.getAllValues();assertEquals(h.get(0),h.get(1));for(int i=2;i<5;i++)assertNotEquals(h.get(0),h.get(i));}
    @Test void historyUsesBoundedDescendingVersionCursor(){var values=new ArrayList<Revision>();for(long i=16;i>=1;i--)values.add(new Revision(ID,TENANT,i,i==1?"CREATE":"UPDATE",draft(),ACTOR,7,TIME));when(repo.history(access(),ID,16,null)).thenReturn(values);var out=data(controller.history(ID,request("GET")));assertEquals(true,out.get("has_more"));assertEquals(2L,out.get("next_before_version"));assertEquals(15,((List<?>)out.get("items")).size());var next=request("GET");next.addParameter("before_version","2");when(repo.history(access(),ID,16,2L)).thenReturn(List.of(values.get(15)));var page=data(controller.history(ID,next));assertNull(page.get("next_before_version"));assertNull(((Map<?,?>)((List<?>)page.get("items")).get(0)).get("previous_version"));}
    @Test void rawQueryUnknownDuplicateAndInvalidPagesFail(){for(String k:List.of("tenant_id","owner_id","activate")){var r=request("GET");r.addParameter(k,"true");status(400,()->controller.current(r));}var duplicate=request("GET");duplicate.addParameter("page_size","10","20");status(400,()->controller.history(ID,duplicate));for(String n:List.of("0","01","21","15.0")){var r=request("GET");r.addParameter("page_size",n);status(400,()->controller.history(ID,r));}var oversized=request("GET");oversized.setQueryString("x".repeat(2049));status(400,()->controller.current(oversized));}
    @Test void mutationsRejectQueryAndMissingKey(){var r=request("POST");r.addParameter("dry_run","true");status(400,()->controller.write(null,input(),r));var noKey=request("POST");noKey.removeHeader("Idempotency-Key");status(400,()->controller.write(null,input(),noKey));}
    @Test void unknownRoleAndMissingSessionFailBeforeBodyParsing(){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"unknown",7,true)));var r=request("POST");r.setContent("{bad".getBytes(StandardCharsets.UTF_8));status(403,()->controller.create(r));status(401,()->controller.current(new MockHttpServletRequest()));verifyNoInteractions(repo);}
    @Test void everyExistingRoleGetsOnlyTheOwnPreferenceCapabilities(){for(String role:List.of("viewer","tadmin","msp","padmin")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));assertEquals(true,data(controller.current(request("GET"))).get("exists"));assertEquals(1L,data(controller.write(null,input(),request("POST"))).get("version"));}}
    @Test void duplicateTrailingAndDeepRawDocumentsFailBeforeWrite(){for(String s:List.of("{\"expected_version\":0,\"expected_version\":1}","{}{}","{\"a\":{\"b\":{\"c\":{\"d\":1}}}}")){var r=request("POST");r.setContent(s.getBytes(StandardCharsets.UTF_8));status(400,()->OwnNotificationPreferenceController.body(r));}}
    @Test void rawByteAndTokenCapsReturn413WithoutTruncation(){var r=request("POST");r.setContent(new byte[8193]);status(413,()->OwnNotificationPreferenceController.body(r));var streamed=new MockHttpServletRequest(){@Override public long getContentLengthLong(){return -1;}};streamed.setContent(new byte[8193]);status(413,()->OwnNotificationPreferenceController.body(streamed));var tokens=request("POST");tokens.setContent(("["+"null,".repeat(64)+"null]").getBytes(StandardCharsets.UTF_8));status(413,()->OwnNotificationPreferenceController.body(tokens));}
    @Test void validRawBodyKeepsExplicitNulls(){var r=request("POST");r.setContent(input().toString().getBytes(StandardCharsets.UTF_8));assertEquals(input(),OwnNotificationPreferenceController.body(r));var fresh=request("POST");fresh.setContent(input().toString().getBytes(StandardCharsets.UTF_8));assertNull(data(controller.create(fresh)).get("requested_quiet_window"));}
    @Test void corruptRepositoryScopeTimestampAndHistoryOrderFailClosed(){var forged=new OwnNotificationPreferenceDraft(UUID.fromString(TENANT),UUID.fromString(OTHER),null,null,null);when(repo.get(access(),ID)).thenReturn(row(1,forged));status(503,()->controller.get(ID,request("GET")));when(repo.get(access(),ID)).thenReturn(new Snapshot("bad",TENANT,1,draft(),ACTOR,7,TIME,TIME));status(503,()->controller.get(ID,request("GET")));when(repo.current(access())).thenReturn(Optional.of(new Snapshot(ID,TENANT,1,draft(),ACTOR,7,TIME,TIME.plusNanos(1))));status(503,()->controller.current(request("GET")));var r=new Revision(ID,TENANT,2,"UPDATE",draft(),ACTOR,7,TIME);when(repo.history(access(),ID,16,null)).thenReturn(List.of(r,r));status(503,()->controller.history(ID,request("GET")));}
}
